package com.veyra.booking;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class BookingStateMachineTest{@Test void valid(){assertDoesNotThrow(()->new BookingStateMachine().check(BookingStatus.CONFIRMED,BookingStatus.DRIVER_EN_ROUTE));}@Test void invalid(){assertThrows(IllegalStateException.class,()->new BookingStateMachine().check(BookingStatus.OPEN_FOR_OFFERS,BookingStatus.IN_PROGRESS));}}